Here is a complete, production-ready Python implementation using the `decimal` module to prevent binary floating-point errors, enforcing non-negative totals, and preventing duplicate promo codes.

```python
from decimal import Decimal, ROUND_HALF_UP
from dataclasses import dataclass, field
from typing import Set, Dict


@dataclass(frozen=True)
class Item:
    name: str
    price: Decimal

    def __post_init__(self):
        if self.price < Decimal("0.00"):
            raise ValueError("Item price cannot be negative.")


@dataclass
class CartItem:
    item: Item
    quantity: int

    def __post_init__(self):
        if self.quantity <= 0:
            raise ValueError("Quantity must be greater than zero.")

    @property
    def total(self) -> Decimal:
        return self.item.price * Decimal(self.quantity)


class ShoppingCart:
    # A registry of valid discounts. 
    # Can be a flat amount (cents/dollars) or a percentage rate.
    AVAILABLE_DISCOUNTS: Dict[str, Dict] = {
        "SAVE10": {"type": "fixed", "value": Decimal("10.00")},
        "FALL20": {"type": "percent", "value": Decimal("0.20")},  # 20% off
        "HALFOFF": {"type": "percent", "value": Decimal("0.50")}, # 50% off
        "BIGSPENDER": {"type": "fixed", "value": Decimal("500.00")},
    }

    def __init__(self):
        self.items: list[CartItem] = []
        self.applied_coupons: Set[str] = set()

    def add_item(self, item: Item, quantity: int = 1) -> None:
        """Adds a product with a specified quantity."""
        self.items.append(CartItem(item=item, quantity=quantity))

    def apply_discount_code(self, code: str) -> None:
        """Applies a discount code. Rejects duplicate or invalid codes."""
        code_upper = code.strip().upper()

        if code_upper in self.applied_coupons:
            raise ValueError(f"Discount code '{code_upper}' has already been applied.")

        if code_upper not in self.AVAILABLE_DISCOUNTS:
            raise ValueError(f"Invalid discount code: '{code_upper}'.")

        self.applied_coupons.add(code_upper)

    @property
    def subtotal(self) -> Decimal:
        """Computes subtotal before any discounts."""
        return sum((ci.total for ci in self.items), Decimal("0.00"))

    def calculate_final_price(self) -> Decimal:
        """
        Calculates final total after all valid discounts.
        Rounds to 2 decimal places and clamps at 0.00.
        """
        subtotal = self.subtotal
        total_deduction = Decimal("0.00")

        # Calculate deductions from all unique applied coupons
        for code in self.applied_coupons:
            promo = self.AVAILABLE_DISCOUNTS[code]
            if promo["type"] == "fixed":
                total_deduction += promo["value"]
            elif promo["type"] == "percent":
                # Percentage applies to the original subtotal
                total_deduction += subtotal * promo["value"]

        final_amount = subtotal - total_deduction

        # Requirement: Price can never be negative
        final_amount = max(Decimal("0.00"), final_amount)

        # Standard financial rounding (half up, 2 decimal places)
        return final_amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


# --- Verification / Example Usage ---
if __name__ == "__main__":
    cart = ShoppingCart()

    # Add items using explicit Decimals
    t_shirt = Item(name="T-Shirt", price=Decimal("19.99"))
    mug = Item(name="Coffee Mug", price=Decimal("7.50"))

    cart.add_item(t_shirt, quantity=2)  # 39.98
    cart.add_item(mug, quantity=1)      #  7.50
    # Subtotal: 47.48

    print(f"Subtotal: ${cart.subtotal}")

    # 1. Apply a valid discount
    cart.apply_discount_code("SAVE10")  # -$10.00
    print(f"After SAVE10: ${cart.calculate_final_price()}")  # 37.48

    # 2. Try applying the same discount again (should fail)
    try:
        cart.apply_discount_code("SAVE10")
    except ValueError as e:
        print(f"Expected Error: {e}")

    # 3. Apply a percentage discount (20% of 47.48 = 9.496)
    cart.apply_discount_code("FALL20")
    # Subtotal (47.48) - 10.00 (SAVE10) - 9.496 (FALL20) = 27.984 -> rounds to 27.98
    print(f"After FALL20: ${cart.calculate_final_price()}")

    # 4. Overwhelming discount (checks non-negative constraint)
    cart.apply_discount_code("BIGSPENDER")  # -$500.00
    print(f"After BIGSPENDER (Floored at zero): ${cart.calculate_final_price()}")
```

### Key Technical Details:
1. **Decimal Precision**: Values are initialized using strings (e.g., `Decimal("19.99")`) to prevent IEEE-754 precision leakage. Final cents are rounded with `ROUND_HALF_UP` to match standard financial rules.
2. **Duplicate Prevention**: Applied coupons are tracked in a `Set[str]`. Trying to apply a code present in the set immediately raises an error.
3. **Non-Negative Guard**: `max(Decimal("0.00"), final_amount)` prevents over-discounting from creating negative balances.

